create_cart:
mutation createCart($lines: [CartLineInput!]!, $buyerIdentity: CartBuyerIdentityInput!, $attributes: [AttributeInput!], $language: LanguageCode, $country: CountryCode) @inContext(language: $language, country: $country) {
  cartCreate(
    input: {lines: $lines, buyerIdentity: $buyerIdentity, attributes: $attributes}
  ) {
    cart {
      ...ShopifyCart
    }
    userErrors {
      field
      message
    }
  }
}

fragment ShopifyCart on Cart {
  id
  checkoutUrl
  totalQuantity
  attributes {
    key
    value
  }
  lines(first: 250) {
    edges {
      node {
        id
        quantity
        attributes {
          key
          value
        }
        cost {
          amountPerQuantity {
            amount
            currencyCode
          }
          totalAmount {
            amount
            currencyCode
          }
          subtotalAmount {
            amount
            currencyCode
          }
        }
        merchandise {
          ...ProductVariant
        }
      }
    }
  }
  discountAllocations {
    discountedAmount {
      amount
      currencyCode
    }
  }
  cost {
    totalAmount {
      amount
      currencyCode
    }
    subtotalAmount {
      amount
      currencyCode
    }
  }
}

fragment ProductVariant on ProductVariant {
  id
  sku
  price {
    amount
    currencyCode
  }
  product {
    id
    description
    title
  }
  image {
    url
  }
  title
  unitPrice {
    amount
    currencyCode
  }
  taxable
  currentlyNotInStock
  selectedOptions {
    name
    value
  }
}

create_checkout:
mutation createCheckout($variantId: String, $location: String, $attributes: [StorefrontCreateCheckoutAttributesElementTypeInput!], $recaptchaToken: String) {
  storefront {
    createCheckout(
      variantId: $variantId
      location: $location
      attributes: $attributes
      recaptchaToken: $recaptchaToken
    ) {
      success
      errors {
        message
        code
        ... on InvalidRecordError {
          model {
            apiIdentifier
            __typename
          }
          validationErrors {
            message
            apiIdentifier
            __typename
          }
          __typename
        }
        __typename
      }
      result
      __typename
    }
    __typename
  }
}

remove_line_item_from_cart:
mutation removeLineItemFromCart($cartId: String!, $lineItemId: String!, $version: Long!, $quantity: Long!, $locale: Locale!) {
  updateMyCart(
    id: $cartId
    actions: {removeLineItem: {lineItemId: $lineItemId, quantity: $quantity}}
    version: $version
  ) {
    id
    version
    isAbleToCheckout
    isRestricted
    isHazardous
    isEmpty
    isDangerous
    splittableSupplyChannelKeys
    isSplit
    discountedPrice {
      centAmount
      currencyCode
      fractionDigits
    }
    customerGroup {
      key
    }
    lineItems {
      ...defaultLineItem
    }
    totalLineItemQuantity
    totalPrice {
      centAmount
      currencyCode
      fractionDigits
    }
  }
}

fragment defaultLineItem on LineItem {
  id
  productId
  productSlug(locale: $locale)
  name(locale: $locale)
  productType {
    id
    version
    name
  }
  totalPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  preDiscountedPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  shippingDetails {
    targets {
      addressKey
      shippingMethodKey
      quantity
    }
    valid
  }
  productKey
  quantity
  variant {
    sku
    key
    images {
      url
    }
    attributesRaw {
      name
      value
    }
  }
  discountedPricePerQuantity {
    discountedPrice {
      includedDiscounts {
        discount {
          id
          key
          description(locale: $locale)
        }
      }
    }
  }
  custom {
    customFieldsRaw {
      name
      value
    }
  }
  supplyChannel {
    id
    key
  }
  lineItemMode
}

set_billing_address:
mutation setBillingAddress($action: SetCartBillingAddress!, $locale: Locale!, $preferredLocale: Locale) {
  setBillingAddress(action: $action) {
    ...CartFragment
    __typename
  }
}

fragment CartFragment on Cart {
  id
  country
  customerId
  customerEmail
  lineItems {
    ...LineItemFragment_Cart
    __typename
  }
  shippingAddress {
    ...AddressFragment
    __typename
  }
  billingAddress {
    ...AddressFragment
    __typename
  }
  shippingInfo {
    shippingMethod {
      id
      key
      name
      __typename
    }
    price {
      ...MoneyFragment
      __typename
    }
    taxedPrice {
      totalNet {
        ...MoneyFragment
        __typename
      }
      totalGross {
        ...MoneyFragment
        __typename
      }
      __typename
    }
    taxRate {
      includedInPrice
      __typename
    }
    discountedPrice {
      value {
        ... on Money {
          ...MoneyFragment
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  totalPrice {
    ...MoneyFragment
    __typename
  }
  taxedPrice {
    totalNet {
      ...MoneyFragment
      __typename
    }
    totalGross {
      ...MoneyFragment
      __typename
    }
    __typename
  }
  discountCodes {
    ...DiscountCodeFragment
    __typename
  }
  discountOnTotalPrice {
    includedDiscounts {
      discount {
        id
        description(locale: $locale)
        fallbackDescription: description(locale: en)
        name(locale: $locale)
        fallbackName: name(locale: en)
        requiresDiscountCode
        __typename
      }
      discountedAmount {
        ...MoneyFragment
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment MoneyFragment on Money {
  currencyCode
  centAmount
  fractionDigits
  __typename
}

fragment LineItemFragment_Cart on LineItem {
  id
  productSlug(locale: $locale)
  fallbackSlug: productSlug(locale: en)
  preferredSlug: productSlug(locale: $preferredLocale)
  lineItemMode
  name(locale: $locale)
  displayBrand
  displayName(locale: $locale)
  quantity
  productId
  productType {
    name
    __typename
  }
  category(locale: $locale)
  price {
    ...ProductPriceFragment
    __typename
  }
  mainImage {
    ...ImageAssetFragment
    __typename
  }
  variant {
    availability {
      noChannel {
        availableQuantity
        expectedDelivery
        __typename
      }
      __typename
    }
    brands {
      name
      value
      __typename
    }
    campaignId
    campaignSlug
    color(locale: $locale)
    gender {
      name
      value
      __typename
    }
    masterScale(locale: $locale)
    size
    sku
    key
    __typename
  }
  totalPrice {
    ...MoneyFragment
    __typename
  }
  taxedPrice {
    totalNet {
      ...MoneyFragment
      __typename
    }
    totalGross {
      ...MoneyFragment
      __typename
    }
    __typename
  }
  taxRate {
    includedInPrice
    __typename
  }
  discountedPricePerQuantity {
    ...DiscountedLineItemPriceForQuantityFragment
    __typename
  }
  __typename
}

fragment ProductPriceFragment on ProductPrice {
  id
  value {
    ...MoneyFragment
    __typename
  }
  country
  discounted {
    value {
      ...MoneyFragment
      __typename
    }
    discount {
      name(locale: $locale)
      description(locale: $locale)
      __typename
    }
    __typename
  }
  custom {
    customFieldsRaw {
      name
      value
      __typename
    }
    __typename
  }
  __typename
}

fragment DiscountedLineItemPriceForQuantityFragment on DiscountedLineItemPriceForQuantity {
  quantity
  discountedPrice {
    includedDiscounts {
      discount {
        id
        description(locale: $locale)
        fallbackDescription: description(locale: en)
        name(locale: $locale)
        fallbackName: name(locale: en)
        requiresDiscountCode
        __typename
      }
      discountedAmount {
        ...MoneyFragment
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment ImageAssetFragment on ImageAsset {
  alt
  aspectRatio
  base64
  bgColor
  height
  id
  sizes
  src
  srcSet
  credits {
    collection
    companyName
    licenseHolder
    photographerUrl
    photographerName
    __typename
  }
  title
  width
  focalPoint {
    id
    x
    y
    __typename
  }
  __typename
}

fragment AddressFragment on Address {
  firstName
  lastName
  streetName
  postalCode
  city
  region
  country
  phone
  additionalAddressInfo
  __typename
}

fragment DiscountCodeFragment on DiscountCodeInfo {
  state
  discountCode {
    id
    code
    name(locale: $locale)
    description(locale: $locale)
    __typename
  }
  __typename
}
